-- 说明：在 v2 基础上加入本轮新增 OCR 的 NLP思维、语言风格、九型人格2 等扫描资料。仍未完成全部扫描件 OCR，覆盖状态见全量读取覆盖报告。
BEGIN;

ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  content = EXCLUDED.content,
  tags = EXCLUDED.tags,
  status = EXCLUDED.status,
  source = EXCLUDED.source,
  sort = EXCLUDED.sort,
  update_time = now();

SELECT setval(pg_get_serial_sequence('rag_documents','id'), GREATEST((SELECT max(id) FROM rag_documents), 1));

COMMIT;
