INSERT INTO rag_documents (id, title, content, tags, status, source, sort, update_time)
VALUES
(100001, '英雄之旅总览：把生命当作创造与疗愈的冒险', '英雄之旅不是追逐名利的个人奋斗剧本，而是一种把生命视为伟大冒险的意识训练：人被某种更深的力量触碰，离开惯性的生活方式，经历失联、磨难、失败、整合与疗愈，最后带着获得的礼物回到世界，贡献给他人。课程正文把这一主线放在当代处境中理解：人很容易陷入负面念头、焦虑、抑郁、过度分析和小我身份，因而失去与生命力、创造力、身体和世界的连接。所谓正能量人生，并不是永远顺利，而是能全身心参与生命，在困难中保持开放，把痛苦转化为更完整的人性。整个十二模块可视为一条路径：听见召唤，看见拒绝，找到向导，训练创造性心智，连接资源，召回温柔、勇猛、顽皮等原型能量，把障碍和恶魔转化为资源，再把礼物传给他人。英雄之旅的核心价值，是让个人从孤立的小我走向身心灵整合，再走向社群与世界的疗愈；每个人都携带一份独特礼物，旅程的意义在于听见它、训练自己承载它、并把它分享出去。它不是一次顿悟，也不是外部成就清单，而是持续的身心练习：安顿、呼吸、放下固化形式，重新选择如何回应生命。用于问答检索时，可对应生命意义、创造力低落、人生卡住、痛苦转化、如何贡献社会等问题。', '["英雄之旅", "创造力", "疗愈整合", "正能量人生", "生命礼物", "社群贡献"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 10, now()),
(100002, '聆听召唤：从童年火光到一生价值的辨认', '召唤不是头脑临时想出的目标，而是生命中反复触碰你的深层信号。它可能来自童年第一次被某个人、一本书、一首音乐、一个科学家或艺术家点亮的瞬间，也可能来自一次巨大的痛苦之后的重生，或来自想象临终回望时会让自己说出此生值得的价值。课程强调，人常被左脑的过度分析锁住，越努力想答案，越难听见召唤；所以练习不是思考清单，而是先安顿身体、呼吸、向天空伸展、向大地释放，再把问题像种子一样投入全身心，让画面、记忆和感受自然浮现。可反复询问：小时候谁启发了我，哪次挣扎让我更有生命力，哪个艺术作品打开过我，若生命将尽我希望完成什么。召唤常常短暂，却不会消失；它像内在已经存在的火，提醒你什么能让生命鲜活、快乐、神奇，也提醒你如何成为更好的自己并帮助别人。当出现多个答案时，不必急着选择哪一个正确，而是观察哪个让身体更放松、更有热、更多泪水或敬畏；这些生理反应常比逻辑判断更接近召唤。', '["召唤", "童年记忆", "生命使命", "身心练习", "价值澄清", "创造力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 20, now()),
(100003, '拒绝召唤与找到向导：把“不可能”转化为支持', '当一个人感到自己想创造某种生命、事业或关系时，拒绝召唤几乎会同步出现。它可能是父母、家庭、社会、性别角色、职业规划或内在批评者的声音，反复说你不能、你不该、那不现实。课程没有把这部分视为错误，而把它看成英雄之旅必经的张力：心中的渴望和头脑中的限制讯息同时存在，真正的成熟不是假装没有阻力，而是能与阻力同场工作。练习的关键，是先触碰心，说出我最想创造的是什么，并让身体做出代表梦想的动作；再走到另一边，进入批评者角色，用姿态和声音表达不允许，重复几次直到能看见它的能量模式；最后请出导师、祖先、榜样或灵性向导，走进他们的身体、眼神和神态，接收支持与许可。向导可以是现实老师、亲人、已故长辈、文学人物或内在智慧。这样做不是否认批评，而是让支持系统比批评更有能量，使人能在真实世界中带着勇气迈步。', '["拒绝召唤", "内在批评", "向导", "导师资源", "身体模型", "自我支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 30, now()),
(100004, '创造性心智：用游戏、幽默和多重视角重新连接生命', '创造性心智的核心是不被单一视角锁住。课程把右脑比作开放的海洋，能把任何事物连接到其他事物；左脑则像语言电脑，擅长代表、分析和控制，但如果成为唯一中心，就会让人困在机器世界，失去心灵、身体和奥秘感。创造性的人会移动、发散、玩耍、幽默，并能像孩子一样流动，同时保有成人的成熟。练习上，可以一天多次收回注意力、触碰心、打开全身通道，暂时放下固定身份，感受自己既是孩子、成年人、古老的生命、大树、动物，也是宇宙的一部分。通过身体动作、声音、笑和想象，人的小我身份会松动，生命意图便能从更广阔的创造意识中表达出来。这种玩耍不是逃避现实，而是让心智恢复灵活性。若发现自己僵硬、无趣、只能想出一种做法，正是需要进入创造性心智的信号。', '["创造性心智", "右脑连接", "左脑分析", "游戏精神", "多重身份", "身体觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 40, now()),
(100005, '三种心智与正念种子：静止、寂静、无边无际', '课程把更深的正念状态分为语言心智、身体心智和场域心智。语言心智容易担忧、解释和计划；身体心智若被紧绷占据，就会阻塞生命之气；场域心智则指人与家庭、城市、自然、社群及万有生命的连接。仅在头脑里设定目标，往往缺少直觉、自信和流动，因此需要把意图放入更精微的身心场域中。三颗种子的练习分别对应三个层面：把静止投入身体，让肌肉和姿态慢下来，像大树向下扎根又向天空打开；把寂静投入语言心智，让杂念在宽阔空间中休息，而不是用力驱赶；把无边无际投入场域心智，让涟漪从心和腹部扩散到周围一切人事物。等身体像光、头脑有寂静、场域能包容时，再说出我想在世界上创造的是什么，创造力会比紧张努力更稳定。', '["三种心智", "正念种子", "语言心智", "身体心智", "场域心智", "生命之气"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 50, now()),
(100006, '三个正向连接：意图、中心与资源圆环', '真正把召唤带到世界，不只是想清楚目标，而是同时建立三个正向连接。第一是简洁、正向、有共振的意图，例如我最想创造的是某种关系、疗愈、平静或贡献；第二是身体中心，可能在心口、腹部或其他最有能量感的地方，当压力、未知、速度过快或注意力涣散时，回到中心就等于回到根基；第三是资源圆环，包含导师、朋友、家人、自然地点、动物、祖先、灵性存有、社群或任何能支持你走路的人事物。练习时先安顿，下沉并打开；再看见未来时间线，一步步前进，每一步都重新感受意图、中心和资源。资源不是抽象安慰，而是一个可被身体感到的场：有人看见你、爱你、理解你、支持你继续。三连可作为任何计划前的微流程：先说清意图，再摸到中心，最后看见资源；三者同时在线时，行动更有弹性和耐力。', '["资源连接", "正向意图", "身体中心", "资源圆环", "时间线", "社群支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 60, now()),
(100007, '三种原型能量：温柔、勇猛与顽皮的整合', '为了让召唤能在沟通和行动中实现，课程提出三种普世原型能量：温柔、勇猛、顽皮。温柔让人先对自己良善，也能在紧张的人际氛围中建立信任和安全；但只有温柔会失去边界，所以需要勇猛的专注、火焰、决心和复原力。勇猛若脱离心灵，会变成暴力、批评或霸凌，因此必须回到人性的中心。顽皮则让人从过度严肃和僵硬中解放出来，带来笑、轻盈、好奇和创造性沟通。练习方式是为每种能量找到代表人物或榜样，进入他们的身体、眼神和姿态，再回到自己身上，用这股能量表达同一个生命意图。成熟表达是三者同时服务于心灵，而不是各自失控。冲突中若只有温柔，容易退让；只有勇猛，容易压迫；只有顽皮，容易逃避深度。', '["原型能量", "温柔", "勇猛", "顽皮", "沟通", "创造力训练"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 70, now()),
(100008, '用原型能量面对障碍：合气道式地欢迎与引导', '障碍在英雄之旅中被称为恶魔，可能是内在恐惧、批评、失联、羞耻，也可能是外在家人、机构、工作环境或不支持你的人。课程借用艾瑞克森取向和合气道精神：不要与阻碍硬碰硬，不要暴力消灭、逃离或控制，而是先与它相合，欢迎它，再把关系带向更好的方向。练习时先站在意图和中心里，看见未来道路，再让一个具体障碍出现在前方。用正向勇猛面对它时，感受边界、眼神、站立方式和可以说出的清晰话语；用顽皮面对它时，跳舞、转圈、笑，避免把力量交给障碍；用温柔面对它时，先支持自己的脆弱，再以成熟善意触碰阻碍背后的痛苦。障碍不是旅程失败的证据，而是提醒你回到中心并调用更完整的自己。', '["障碍转化", "恶魔", "合气道", "非暴力", "边界", "原型应用"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 80, now()),
(100009, '转化恶魔：从问题行为里识别正向需求', '问题、症状和成瘾行为表面上像敌人，深处常隐藏着尚未被看见的正向需求。课程用恶龙可能是等待被发现的礼物来说明这一点：如果只分析、压制、逃避或攻击问题，就会切断它携带的资源。更有效的方法是发展身体模型。选择一个反复让你挣扎的行为或情绪，例如焦虑、缺乏安全感、拖延、上瘾；不要急着解释，不要命令它停止，而是让身体自然做出一个姿态或重复动作，并以比平常慢数倍的节奏、温柔和好奇来体验它。然后在动作中询问：这个模式想为我创造什么，它想满足哪种正向需求。关键在于区分需求和策略：需求可能是安全、温暖、休息、连接或自由，旧策略可以被替换，但需求必须被尊重。', '["恶魔转化", "身体模型", "正向需求", "症状意义", "艾瑞克森", "成瘾疗愈"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 90, now()),
(100010, '目标与障碍整合：让对立面成为同一支舞', '目标和障碍并不总是敌对关系，很多症状其实在尝试恢复平衡。一个人用紧绷、强硬和肌肉力量逼自己完成项目，结果拖延不断出现；拖延看似恶魔，深处却可能代表放松、休息、释放和阴性能量，提醒他不能只靠蛮力。整合练习先为目标建立身体模型，感受我真正想创造的是什么；再为每当我想创造它时被触发的那一面建立身体模型，如抑郁、自我批判、恐惧、愤怒或拖延。不要用对错评判两边，而是用缓慢、温柔、顽皮、好奇的动作欢迎每一面，倾听它各自代表的正向需求。整合后的行动不是折中妥协，而是让目标获得障碍所携带的智慧：努力获得休息，勇气获得柔软，前进获得节奏，因此更能长期持续。', '["目标整合", "障碍整合", "阴阳平衡", "拖延", "身体舞蹈", "创造性完整"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 100, now()),
(100011, '传递给他人：把获得的礼物变成世界的光', '英雄之旅最终不是把天分囤积起来，而是传递给他人。课程通过艾瑞克森对学生的教导指出，真正的回报方式是把有用的东西继续分享。一个人在年轻时需要专注自己的目标，但当能力和成功逐渐出现，如果只追逐名利、金钱和外在认可，创造力会再次收缩；若把天赋视为被托付的礼物，并用来帮助别人，生命会更快乐、更宽广。练习上，先放下比较、表演和赚钱的压力，进入让自己感到神圣、平静、合一的空间，感受内在不可摧毁的光。分享不是拯救姿态，也不是牺牲自我，而是让自己的觉醒映照并唤醒他人的觉醒。真正分享时必须先保持自己的光，不在关系中耗尽自己，而是从充满的中心去照亮。', '["传递给他人", "贡献", "礼物", "艾瑞克森", "慈悲练习", "社群疗愈"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 110, now()),
(100012, '回顾整合：把每一天活成完整的英雄之旅', '最后的整合练习把十二个模块收束为日常道路：先安顿、下沉大地、向天空打开，让语言像音乐和梦一样流入全身；记得自己来到世界是为了给出一份礼物，也诚实看见曾经因为不被支持而转身拒绝。然后寻找榜样、向导和能让灵魂相触的人，学习把觉知中心从头脑转回身体、心灵和场域。日常行动中，要保留玩耍、温柔、勇猛、专注和严肃的混合状态；遇到障碍时，退后一步成为大树，回到静止、寂静和无边无际，再用身体模型、合气道式欢迎和创造性好奇把冲突转为合作。英雄之旅不是一次性完成的课程，而是每一天都能重新选择的活法：过好今天，享受这一刻，并支持他人也活出他们的旅程。', '["回顾整合", "每日练习", "感恩", "宽恕", "宇宙连接", "享受生命"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 120, now()),
(100013, '1号完美型：核心识别与成长建议', '1号的核心不是简单的爱挑剔，而是内在长期有一套高标准在审判：这件事对不对、够不够好、还能不能改进。他们把责任、秩序、原则和正确性放在快乐之前，擅长发现漏洞、维护规范、把事情做扎实。盲点是把应该当成唯一道路，把错误看成道德问题，把愤怒压成不满、讽刺、僵硬的礼貌或反复纠错。成长关键是从内在批评家退后一步，区分我想要和我应该，允许错误、风险和多种答案存在；把事实核对代替脑内定罪，把感谢与肯定说出口；给日程留白，练习享受、求助和适度妥协；把怒气视为被忽略需求的信号，用清楚、非控诉的语言表达边界。成熟的1号会把高标准转化为可靠、正直和持续改善，而不是让自己和他人永远不合格。', '["九型人格", "1号", "完美型", "完美主义者", "内在批评", "愤怒", "原则", "成长建议"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 210, now()),
(100014, '2号助人型：核心识别与成长建议', '2号的核心驱动力是通过被需要、被喜欢、被认可来确认自己的价值。他们能快速捕捉他人的情绪和需求，愿意支持、照顾、连接资源，也善于让别人感觉自己很重要。盲点是注意力长期放在他人身上，自己的真实需要会变得模糊，付出容易夹带期待：我这么懂你、帮你，你是否也会爱我、重视我？得不到回应时，2号可能受伤、抱怨、控制、吃醋。成长建议是停止用过度付出来换取关系安全，帮助前先问：这是对方真正需要，还是我想证明自己重要？把隐性期待改成直接请求，允许自己接受照顾；建立边界，不把拒绝理解为不爱。成熟的2号能温暖地滋养他人，也能诚实承认自己的欲望、脆弱和限度。', '["九型人格", "2号", "助人型", "给予者", "被需要", "认可", "边界", "关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 220, now()),
(100015, '3号成就型：核心识别与成长建议', '3号的核心关注是成功、效率、形象和可见成果：我怎样被尊敬、被认可、被证明有价值。他们行动快、目标感强、能读懂场域并切换角色，适合推动项目、包装想法、销售愿景、鼓舞团队。代价是把正在做什么误当成我是谁，把悲伤、恐惧、疲惫和亲密需求视为影响表现的干扰。成长方向是从表演自我回到诚实自我：定期停下问自己喜欢什么、不喜欢什么、身体感觉如何；把休息和情感觉察也放进日程，而非只安排产出；学习承认失败、困惑和普通时刻，不急着换项目或换形象。成熟的3号依然高效有感染力，但其价值不再完全依赖掌声。', '["九型人格", "3号", "成就型", "实干者", "形象", "成功", "工作狂", "诚实"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 230, now()),
(100016, '4号自我型：核心识别与成长建议', '4号的核心经验是强烈地感到我与别人不同，并在失落、渴望、独特性和真实表达中寻找自我。他们情感细腻，能进入他人的痛苦，富有审美、创造力和意义感。盲点是注意力容易停在缺失处：现实有什么不够，别人拥有什么而我没有，理想关系为何迟迟不到；情绪会被当成身份，嫉妒、忧郁、浪漫化和戏剧性表达会反复出现。成长建议是尊重情感但不被情感定义：把我感觉如此与事实必然如此分开；在普通日常中建立稳定行动；把嫉妒当成愿望线索，转化为可执行选择；亲密关系中直接表达需要，少用疏离、戏剧化或测试来证明爱。', '["九型人格", "4号", "自我型", "悲情浪漫者", "情绪", "嫉妒", "真实", "创造力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 240, now()),
(100017, '5号理智型：核心识别与成长建议', '5号的核心策略是用观察、知识和边界来保护时间、能量与内在空间。他们擅长客观分析、系统研究、保持冷静，常在独处后才重新接触情绪。压力点在于把外界需求体验成侵入，把亲密、承诺或即时回应视为资源消耗，于是退回头脑、分隔生活领域、少说少给；情绪可能不是没有，而是被推迟到安全独处时才浮现。成长建议不是强迫外向，而是让知识与生命重新连接：在尚未准备完美时也小步参与；用简短语言告诉别人自己需要多少时间和空间，而不是消失；练习在当下辨认身体和情绪，别只事后复盘。', '["九型人格", "5号", "理智型", "观察者", "边界", "知识", "抽离", "独处"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 250, now()),
(100018, '6号忠诚型：核心识别与成长建议', '6号的核心注意力在安全、信任、风险和权威：哪里会出问题，谁可靠，我的决定是否稳妥。他们能预演最坏情况，发现隐藏漏洞，对团队和承诺很忠诚。盲点是焦虑会让他们在顺从与挑战权威之间摆动，既想得到保护又担心被控制；他们可能怀疑他人动机、拖延决定、反复确认，或用反恐惧方式冲向危险来证明自己不怕。成长建议是发展内在权威：把事实、想象、直觉和投射分栏记录；为决策设定截止时间，允许足够好而非绝对安全；公开提出疑问，不在背后累积猜测；练习想象正面结果，让身体体验安全。', '["九型人格", "6号", "忠诚型", "怀疑论者", "安全", "信任", "权威", "焦虑"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 260, now()),
(100019, '7号快乐型：核心识别与成长建议', '7号的核心追求是可能性、自由、快乐和未来计划。他们乐观、点子多、反应快，能把不同事物连接成新方案，擅长带来兴奋感、创新气氛和对未来的信心。盲点是害怕被限制、无聊或痛苦困住，容易用新选择、合理化、玩笑和忙碌避开难受感；承诺后仍保留退路，兴趣下降就转向下一个刺激，未完成事项堆积。成长建议是把自由从永远有别的选择升级为能选择并完成：限制同时进行的项目，给承诺设置收尾标准；遇到痛苦时先停留、呼吸、命名感受，不急着转移；评估计划时同时看风险、资源和代价。', '["九型人格", "7号", "快乐型", "享乐主义者", "自由", "乐观", "选择", "逃避痛苦"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 270, now()),
(100020, '8号领袖型：核心识别与成长建议', '8号的核心关注是力量、控制、公正和真实。他们直接、有行动力，能在混乱中接管局面，保护弱者，讨厌虚伪、软弱和被蒙在鼓里。压力点在于把世界分成强者与弱者，隐藏脆弱，用愤怒、强势和报复来恢复控制，可能无意中让他人害怕或沉默。成长建议是把力量从压制转为承担：行动前先听完整信息，尤其欢迎坏消息；区分我在保护与我在控制；练习用较低强度表达需求，给别人反应时间；在可信对象面前承认害怕、在乎或受伤，不把柔软等同于失败；冲突中追求清楚和修复，而不只是胜利。', '["九型人格", "8号", "领袖型", "保护者", "控制", "正义", "愤怒", "脆弱"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 280, now()),
(100021, '9号和平型：核心识别与成长建议', '9号的核心策略是维持和谐、避免冲突，并把自己融入他人的节奏。他们能倾听多方、理解不同立场、提供稳定支持，是天然的调停者。盲点是忘记自己的优先级，把重要愿望让位给琐事、习惯或他人安排，表面顺从内心保留，压力下以拖延、麻木、被动抵抗表达愤怒。成长建议是把和平从没有冲突升级为真实参与：每天写下自己的一个偏好、一个不愿意、一个下一步行动；用期限和结构帮助聚焦，先做最重要的小步骤；练习直接表达不同意见，不用拖延让别人猜；把愤怒视为生命力和边界的信号。', '["九型人格", "9号", "和平型", "调停者", "和谐", "冲突回避", "惯性", "边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 290, now()),
(100022, '通用机制：注意力焦点、直觉与三大中心', '九型不是先看外在行为，而是看注意力被什么自动吸走。性格一旦形成，人会选择性搜集信息：1号看对错与改进，2号看别人是否需要和喜欢自己，3号看表现能否获得肯定，4号看缺失、独特和真实感，5号看边界与资源要求，6号看风险和隐藏意图，7号看快乐选择与未来可能，8号看失控、不公和力量对比，9号看他人安排与各方立场。身体中心8、9、1常通过腹部和本能感知环境；情感中心2、3、4通过关系、形象和情绪共鸣感知；精神中心5、6、7通过观察、预测和联想感知。成长入口是成为内心观察者：记录自己第一时间注意到什么、忽略什么；区分事实、解释、幻想和直觉。', '["九型人格", "通用机制", "注意力", "直觉", "三大中心", "身体中心", "情感中心", "精神中心"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 310, now()),
(100023, '通用机制：两翼、核心动机与同型差异', '两翼指某个型号相邻两侧型号对其表达方式的影响。它不是另一个核心类型，也不是简单的副人格，而是让同一型号呈现不同气质的调味层：偏5翼的4号可能更内收、理性和孤僻，偏3翼的4号可能更外显、形象化和有舞台感；偏8翼的9号更硬、更能顶住压力，偏1翼的9号更克制、更在意正确与秩序。使用两翼时要避免只凭风格判断，例如一个强势的9号不等于8号，一个外向的5号也不等于7号。先问核心动机：他是在维护和谐、保留资源，还是追求自由？再看两翼怎样改变表达。两翼解释差异，不替代访谈、情境和长期注意力观察。', '["九型人格", "通用机制", "两翼", "核心动机", "同型差异", "识别方法"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 320, now()),
(100024, '通用机制：压力线、安全线与状态变化', '每个型号不是静态标签，而是由日常主型、压力状态、安全状态共同构成。压力状态常沿箭头离开本型：1到4、2到8、3到9、4到2、5到7、6到3、7到1、8到5、9到6；安全状态常沿反向进入：1到7、2到4、3到6、4到1、5到8、6到9、7到5、8到2、9到3。使用时不要把安全线等同于一定健康、压力线等同于一定糟糕；安全也可能暴露阴影，压力也可能激发能力。关键是观察状态变化：在放松、受威胁、被爱、被批评时你变成什么样？成长不是迷恋安全态，而是能觉察三种状态、整合其正面资源，并在负面反应出现前暂停选择。', '["九型人格", "通用机制", "压力线", "安全线", "动态变化", "九角星", "状态识别"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 330, now()),
(100025, '通用机制：关系与职场沟通的九型用法', '九型用于关系和职场时，重点不是给人分类，而是找到对方的原动力、焦虑点和沟通入口。1号需要尊重其标准，同时减少你错了的羞辱感；2号需要感谢但也要鼓励其说出真实需求；3号需要目标和认可，也要提醒其关注人和过程；4号需要真实与意义，反馈要避免轻率否定其感受；5号需要提前信息、边界和思考时间；6号需要透明、稳定承诺和可验证依据；7号需要空间与愿景，同时要明确收尾责任；8号需要直说、完整信息和可信赖的边界；9号需要清晰结构、温和追问和表达异议的安全感。成熟用法是用类型翻译彼此语言：把评判译成对质量的在乎，把控制译成对安全的需求，把拖延译成冲突恐惧，再讨论可执行请求。', '["九型人格", "关系", "职场", "沟通", "领导力", "反馈", "冲突", "团队管理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 340, now()),
(100026, '关键对话：先恢复安全感，再讨论观点差异', '关键对话通常同时具备三个特征：观点不同、利害关系重大、情绪强烈。很多沟通失败不是因为道理不够，而是对话安全感已经破裂；一旦人感觉被攻击、羞辱或不被尊重，就会转入沉默或暴力：沉默包括回避、掩饰、退出，暴力包括控制、贴标签、攻击和打断。有效处理关键对话的第一步，不是立刻证明自己正确，而是观察气氛是否安全：对方是否还愿意说真话，自己是否还在听。若安全感下降，应先暂停内容争论，说明共同目的和尊重，例如“我不是要否定你，我想一起把问题解决”。然后再陈述事实、表达感受、解释自己的故事、询问对方看法。App 问答可用于伴侣冲突、上下级反馈、客户沟通和团队分歧。', '["关键对话", "沟通", "安全感", "冲突", "反馈", "沉默", "暴力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 410, now()),
(100027, '非暴力沟通四步：观察、感受、需要、请求', '非暴力沟通的核心，是把注意力从评判、指责、命令和辩解，转向人真实的观察、感受、需要和请求。第一步是观察：具体说发生了什么，避免“你总是”“你从来不”等概括性评价。第二步是感受：表达自己身体和情绪的真实状态，如失落、担心、疲惫、安心，而不是伪装成感受的指责。第三步是需要：为自己的感受负责，看到背后未被满足的需要，如尊重、休息、连接、自由、安全、理解。第四步是请求：提出具体、可执行、当下可回应的请求，而不是模糊期待或命令。它并非软弱妥协，而是让双方从敌对意识回到生命需要。适合回答亲密关系争吵、亲子沟通、职场表达、如何提出边界和如何道歉。', '["非暴力沟通", "观察", "感受", "需要", "请求", "同理心", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 420, now()),
(100028, '情绪急救：拒绝、孤独、失败和反刍需要及时处理', '日常心理伤害也需要像身体伤口一样做急救。拒绝会带来尖锐痛感，削弱自尊和归属感；孤独会让人更敏感、更防御，甚至把真正能靠近的人推开；失败容易让人把一次结果扩大成对自我的否定；反刍会让痛苦反复激活，形成焦虑和抑郁倾向。情绪急救的第一原则是尽早处理，而不是硬扛。可以先给情绪命名，承认痛苦真实存在；再把事件与自我价值拆开，避免“我被拒绝=我不值得”；随后做具体修复：联系安全的人、恢复日常行动、减少反复回放、写下可学习之处。若痛苦持续影响睡眠、工作、饮食、现实判断或有自伤风险，应寻求专业帮助。App 可用于被拒绝、失恋、孤独、失败、自卑和内耗等场景。', '["情绪急救", "拒绝", "孤独", "失败", "反刍", "自尊", "心理创伤"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 430, now()),
(100029, '自控力：先观察失控模式，再设计环境', '自控不是靠羞辱自己变强，而是成为自己的观察者，理解何时、何地、因为什么失控。很多人越相信自己意志坚定，越容易把自己暴露在诱惑中；一旦失败，又因为意外和羞耻而放弃。更有效的方法是像科学家一样收集数据：什么时候最容易拖延，什么情绪会触发消费或暴食，哪些人、地点、App 或疲劳状态会削弱自控。然后设计环境而不是只发誓：减少诱惑可见度，提前设定下一步动作，把长期目标和眼前选择连接起来，用小实验测试哪种方法有效。自控力还包含“我要做”“我不要”“我想要”三种力量：不仅要抵制诱惑，也要记得真正重要的目标。App 可用于拖延、成瘾、情绪性消费、减肥、学习和习惯改变。', '["自控力", "意志力", "拖延", "习惯改变", "观察者", "诱惑", "目标"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 440, now()),
(100030, '解决冲突：把冲突当作信息，而不是立即消灭', '冲突不可完全避免，重要的是把它当作信息入口，而不是马上逃跑、压制或赢过对方。高质量冲突处理从理解发生了什么开始：双方各自看到了什么事实，分别受到什么影响，各自真正关心什么。很多人一遇冲突就急着解决，反而没弄清原因；也有人任由敌意升级，错失修复机会。有效做法是先降低攻击性表达，帮助聆听和说话变得容易：少用指责，多用具体事件；少说“你就是”，多问“你当时看到的是什么”；承认对方处境，同时表达自己的边界和请求。冲突的目标不是双方都委屈地妥协，而是找到能照顾重要需要的新路径。App 可用于伴侣冷战、团队矛盾、朋友误会、谈判和家庭分歧。', '["解决冲突", "聆听", "对话", "边界", "关系修复", "谈判", "误会"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 450, now()),
(100031, '创伤反应：身体会记住未完成的危险', '创伤并不只是记忆里的一段故事，也会保存在身体、神经系统和关系反应中。经历过创伤的人可能明知现在安全，却在类似声音、气味、表情、距离或权威情境中突然紧绷、麻木、愤怒、逃离或讨好；这不是矫情，而是身体在用旧系统保护自己。疗愈的核心之一是重新建立安全与调节能力：先识别触发点和身体信号，再用呼吸、地面感、身体移动、稳定关系和可预测环境帮助神经系统回到当下。不要急着逼自己讲完所有创伤细节，身体安全比叙事完整更基础。关系中，创伤者需要被看见、被尊重节奏，而不是被催促“想开点”。App 可用于惊恐、麻木、过度警觉、亲密关系触发和创伤后自我理解。', '["创伤疗愈", "身体记忆", "安全感", "神经系统", "触发点", "情绪调节", "依恋"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 460, now()),
(100032, '回避型模式：逃避情绪会让关系和自我更空', '回避型或逃避型人格模式常见于对拒绝、失望、犯错和暴露脆弱高度敏感的人。为了不被伤害，他们会隐藏不安全感，努力保持理性、独立、无所谓，甚至把真实情绪像流感一样躲开。短期看，逃避能减少痛苦；长期看，它会让人失去与自己和他人的情绪连接，形成空虚、焦虑、亲密困难和自我价值感低落。成长不是一次性冲进情绪，而是安全地接触：当想逃跑、责备或麻木时，先停下，命名身体感受和脑中故事；区分真实事件与旧信念；用小剂量表达需要和脆弱，观察关系是否真的崩塌。App 可用于回避亲密、不敢表达、不安全依恋、内心空虚和情绪逃避。', '["回避型人格", "不安全依恋", "情绪逃避", "亲密关系", "脆弱", "自我价值", "焦虑"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 470, now()),
(100033, '边界表达：清楚说不，不等于伤害关系', '很多关系问题不是缺少爱，而是缺少清楚边界。没有边界的人容易讨好、压抑、拖延、爆发；边界过硬的人则可能控制、隔离、拒绝连接。健康边界是既承认关系重要，也承认自己的时间、身体、情绪和价值同样重要。表达边界时，先具体说明事实和影响，再表达自己的限制和可提供的替代方案，例如“我今晚需要休息，不能继续讨论；明天十点我可以认真听你说”。边界不是惩罚，也不是让对方猜，而是让关系可持续。若对方不适应你的新边界，不代表你错了；这只是关系系统在重新调整。App 可用于不会拒绝、被索取、关系内耗、职场加班、人情压力和亲密关系空间。', '["边界", "拒绝", "讨好", "关系内耗", "自我照顾", "沟通", "亲密关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 480, now()),
(100034, '行动改变：把大目标拆成可重复的小实验', '无论是九型成长、英雄之旅还是自控力训练，真正改变都需要从宏大愿望落到小实验。大目标容易激发热情，也容易引发压力、完美主义和拖延；小实验则让人用数据学习，而不是用自责消耗。设计实验时要明确：我要观察什么，下一步最小行动是什么，何时做，做完如何记录。比如想改善沟通，不是发誓以后不吵架，而是每次冲突前先说一个事实、一个感受、一个请求；想减少拖延，不是要求自己从此自律，而是先开始5分钟并记录触发点。失败不是人格失败，而是实验数据，提醒你调整环境、节奏、支持或目标。App 可用于习惯养成、学习计划、关系修复、情绪管理和职业目标推进。', '["行动改变", "小实验", "习惯养成", "拖延", "目标拆解", "复盘", "成长练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 490, now()),
(100035, '关系修复：先承认影响，再解释动机', '关系受伤后，很多人急着解释自己不是故意的，却忽略对方已经受到影响。修复对话应先承认事实和影响：我看到我刚才打断你，让你觉得不被尊重；再表达自己的感受和需要；最后提出可执行的修复请求或承诺。解释动机可以放在后面，因为如果先解释，容易被听成辩解。修复也包括聆听对方版本，不急着纠正其中每个细节。道歉不是自我贬低，而是对关系的负责；原谅也不是立刻恢复原状，而是双方重新建立安全感和边界。若伤害反复发生，修复需要具体行为变化，而不只是情绪表达。App 可用于道歉、冷战后复联、伴侣争吵、朋友误会、亲子冲突和职场关系恢复。', '["关系修复", "道歉", "影响", "安全感", "冷战", "亲密关系", "沟通模板"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 500, now()),
(100036, '福格行为模型：行为发生要同时具备动机、能力与提示', '当用户说“我知道该做但就是做不到”时，优先从行为设计入手。一个行为要发生，通常需要动机足够、能力门槛足够低、提示在正确时间出现。动机最不稳定，不能把改变押在热血上；更可靠的方式是把行为缩小到几乎不会失败，并绑定已有习惯。比如“刷牙后做一次深呼吸”“进门后先问一句今天怎么样”。先让行为发生，再让身份感和自信跟上。', '["行为改变", "福格模型", "微习惯", "动机", "提示", "自控"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 36, now()),
(100037, '微习惯设计：小到不会失败，才容易长期坚持', '很多改变失败不是因为目标太小，而是第一步太大。微习惯的关键是把行动拆到两分钟内可完成，先追求“出现”而不是“完美”。用户想读书，可先设为“打开书读一段”；想运动，可先设为“穿上鞋出门站一分钟”。完成后及时给自己一个正向标记，让大脑把新行为和成就感连接起来。稳定后再自然加量，而不是一开始靠逼迫冲刺。', '["微习惯", "行动设计", "成长", "自我效能", "坚持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 37, now()),
(100038, '习惯回路：找出提示、惯常行为和奖励', '习惯不是单个动作，而是“提示—惯常行为—奖励”的回路。想改变坏习惯，先观察它通常在什么时候、什么情绪、什么地点、和谁在一起时发生，再识别真正奖励：是放松、逃避压力、获得刺激，还是寻求连接。不要只删除行为，而要保留奖励、替换动作。例如压力大就刷短视频，可能真正需要的是短暂恢复；可替换成五分钟散步、伸展或给朋友发一句话。', '["习惯回路", "行为改变", "奖励", "提示", "替代行为"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 38, now()),
(100039, '自控力不是硬扛，而是提前设计环境', '自控力资料的核心提醒是：越到诱惑现场才靠意志力，越容易失败。更有效的是提前改环境，让好行为更容易、坏行为更麻烦。想少刷手机，把手机放远、关通知、设置固定查看窗口；想控制饮食，不把高诱惑食物放在手边；想避免情绪化回复，先写草稿不发送。自控不是讨厌自己，而是承认人会受情境影响，然后温和地设计情境。', '["自控力", "环境设计", "意志力", "诱惑", "行为改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 39, now()),
(100040, '拖延的背后常是情绪调节，而不是懒', '拖延往往不是时间管理问题，而是情绪管理问题：任务让人感到羞耻、恐惧、无聊或无力，于是大脑选择短期缓解。处理拖延时，不要只问“怎么提高效率”，先问“我在回避哪种感受”。可把任务拆成下一步可见动作，并设置低压力开始仪式：只做五分钟、只写标题、只打开文件。开始后焦虑下降，行动会反过来带来掌控感。', '["拖延", "情绪调节", "行动", "自我效能", "任务拆解"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 40, now()),
(100041, '认知觉醒：改变先从注意力回到当下开始', '成长不是一口气重塑人生，而是逐步看见自动反应。认知觉醒强调把注意力从模糊焦虑拉回具体事实：我现在在想什么、身体有什么感觉、下一步最小行动是什么。用户陷入“我不行、来不及、都完了”时，可先把大问题拆成可观察的场景和可执行的十分钟行动。觉察不是想明白一切，而是让自己从自动驾驶切回主动驾驶。', '["认知觉醒", "注意力", "自我改变", "行动", "觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 41, now()),
(100042, '成长型改变：先做实验，不急着定义自己', '当用户把一次失败解释成“我就是这种人”，改变会被身份标签锁死。更好的语言是实验：这次策略不适合我，下一次换一个提示、环境或支持方式。把改变当实验，可以降低羞耻感，也能保留复盘能力。每次只调整一个变量，例如时间、地点、同行者、任务大小或奖励方式。真正重要的不是一次做对，而是形成可迭代的自我更新系统。', '["成长", "实验思维", "复盘", "身份", "行为改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 42, now()),
(100043, '焦虑自助：先区分真实问题和假想灾难', '焦虑会把可能性伪装成确定性，让人提前生活在最坏结果里。处理时先写下担心内容，再分成两类：真实可行动的问题，和目前无法验证的灾难想象。前者列出下一步行动；后者练习延迟担心、回到身体和现实证据。不要和焦虑争辩“别想了”，而是问：我现在能做哪一个具体动作？如果不能行动，我能否先照顾身体，让神经系统降档？', '["焦虑", "认知行为", "担心", "情绪调节", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 43, now()),
(100044, '情绪粒度：说得越准确，越容易选对行动', '“我很烦”通常太粗糙，无法指导行动。情绪粒度训练是把模糊难受细分：委屈、羞耻、嫉妒、失望、担心、孤独、被忽视、无力、愤怒。不同情绪需要不同回应：失望需要调整期待，羞耻需要自我接纳，愤怒常提示边界，孤独提示连接需求。App 回答情绪问题时，应先帮用户命名感受，再从感受背后的需要进入行动建议。', '["情绪", "情绪粒度", "自我觉察", "需要", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 44, now()),
(100045, '情绪急救：心理小伤也要及时处理', '拒绝、孤独、失败、反刍和自责就像心理擦伤，如果不处理会扩大成长期痛苦。情绪急救的重点不是立刻积极，而是防止二次伤害：不要用一次拒绝证明自己不值得，不要让失败变成全面否定，不要在脑内反复播放羞辱场景。可用三步处理：承认受伤，给出多个解释，做一个能恢复自尊或连接的小行动。', '["情绪急救", "拒绝", "孤独", "失败", "自尊"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 45, now()),
(100046, '创伤反应：身体会先于理性进入防御', '创伤相关资料提醒，很多“反应过度”其实是身体把当下误判为过去的危险。用户突然僵住、爆发、逃离、麻木，并不一定是矫情，而可能是神经系统进入战斗、逃跑、冻结或讨好。支持方式不是逼自己马上讲道理，而是先恢复安全：看见周围环境、触碰稳定物体、慢慢呼气、让身体知道此刻已经不同于过去。稳定后再处理故事和意义。', '["创伤", "身体反应", "安全感", "神经系统", "疗愈"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 46, now()),
(100047, '愤怒的积极功能：它常在提醒边界被侵犯', '愤怒并不总是坏情绪，它常提示某个边界、价值或需求被忽视。问题不在愤怒本身，而在表达方式。用户生气时可先问：我在保护什么？我希望对方停止什么、开始什么、理解什么？等身体降温后，用边界句表达：“当发生 X 时，我感到 Y，因为我需要 Z；下次请具体做 A。”这样既不压抑愤怒，也不让愤怒变成攻击。', '["愤怒", "边界", "情绪管理", "需求", "表达"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 47, now()),
(100048, '抑郁低谷：先恢复行动循环，再追求意义感', '抑郁状态会让人失去动力，而失去行动又会进一步降低情绪。支持用户时，不宜只说“想开点”。更实用的是行为激活：每天安排极小、可完成、可记录的行动，如洗澡、晒太阳、走五分钟、整理一小块桌面、联系一个安全的人。行动不是为了立刻开心，而是重建“我还能影响一点点生活”的证据。必要时建议寻求专业支持。', '["抑郁", "行为激活", "低谷", "行动", "支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 48, now()),
(100049, '反刍思维：把脑内复盘变成纸面问题', '反刍会让人以为自己在解决问题，实际是在重复痛苦。识别标志是：想了很久却没有新信息、没有行动、情绪更糟。可把脑内循环写成三个问题：我正在反复想哪句话？它对应的事实证据是什么？我能采取的最小行动是什么？如果没有行动，就给担心设置时间盒，转向身体活动或连接他人。把想法落到纸面，能把情绪风暴变成可处理对象。', '["反刍", "焦虑", "情绪急救", "书写", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 49, now()),
(100050, '存在焦虑：意义不是找到标准答案，而是承担选择', '存在主义心理治疗提醒，人的痛苦不只来自症状，也来自自由、孤独、死亡和意义感。用户问“我到底为什么活着”时，不必急着给鸡汤答案。可以引导其看见：意义往往不是被发现的固定物，而是在选择、关系、创造和承担中生成。先从一个愿意负责的小选择开始：今天我想怎样对待身体、关系、工作或某个重要价值？', '["存在主义", "意义感", "选择", "自由", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 50, now()),
(100051, '依恋系统：亲密关系里的追和躲都是求安全', '亲密关系中的“追问”和“冷处理”常不是单纯作或无情，而是两种安全策略。焦虑型通过靠近、确认、解释来降低不安；回避型通过拉开距离、沉默、强调独立来恢复掌控。若双方只攻击表层行为，就会形成越追越逃。修复时要翻译需求：追的一方需要可预期回应，躲的一方需要不被淹没的空间。先约定冷静时长和恢复沟通时间，比无限争对错更有效。', '["依恋", "亲密关系", "追逃循环", "安全感", "沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 51, now()),
(100052, '爱的五种语言：用对方能接收的方式表达爱', '很多关系并非没有爱，而是表达通道错位。爱的五种语言包括肯定的话语、高质量陪伴、接受礼物、服务行动和身体接触。用户可以观察伴侣最常抱怨什么、最常主动给出什么、最容易因什么感动，来判断主要爱语。关系经营不是只用自己喜欢的方式付出，而是学习对方能接收的方式，同时也清楚告诉对方自己需要什么。', '["亲密关系", "爱的五种语言", "伴侣", "表达爱", "需求"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 52, now()),
(100053, '伴侣冲突：先分清事实、解释和感受', '伴侣争吵常把事实、解释和感受混在一起：“你又不在乎我”其实可能包含事实“你迟到了三十分钟”、解释“你不重视我”、感受“我失望和不安”。修复时先拆开三层，事实越具体越少争议，解释越开放越能对话，感受越真诚越容易被听见。可以说：“你晚到三十分钟时，我脑中解释成自己不重要，所以很失落。我想知道实际发生了什么。”', '["伴侣沟通", "冲突修复", "事实", "感受", "解释"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 53, now()),
(100054, '亲子沟通：先连接，再纠正', '儿童沟通资料的一个关键原则是：孩子在被理解前很难真正听见道理。亲子冲突中，先描述孩子可能的感受和愿望，再谈规则与后果。比如“你很想继续玩，所以被叫停很生气”，比“别闹了”更能降低防御。连接不是纵容，而是先让孩子的大脑从对抗状态回到可学习状态。之后再给有限选择和清晰边界。', '["亲子沟通", "儿童心理", "连接", "边界", "情绪"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 54, now()),
(100055, '家庭关系中的边界：爱不是互相吞没', '家庭里常把“我都是为你好”当成越界理由。健康边界不是冷漠，而是区分谁的情绪、选择和后果由谁负责。用户面对父母、伴侣或孩子的压力时，可用三句式：我理解你的担心；这件事我会自己决定；我愿意在某个范围内和你讨论。边界需要温和重复，不必每次都证明自己有资格说不。', '["家庭关系", "边界", "自主", "沟通", "责任"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 55, now()),
(100056, '人际游戏：反复上演的冲突通常有隐藏收益', '沟通分析资料强调，有些冲突像固定剧本：表面在解决问题，实际在重复熟悉角色，例如“你看我多可怜”“你总是错”“只有我能救你”。这些游戏会带来隐藏收益：避免真正亲密、证明旧信念、获得注意或逃避责任。识别方法是看结局是否总相似、情绪是否熟悉、双方是否越谈越远。退出游戏的第一步，是拒绝继续扮演被分配的角色。', '["沟通分析", "人际游戏", "关系模式", "责任", "冲突"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 56, now()),
(100057, '讨好型关系：把“被喜欢”从生存需求降级为普通愿望', '讨好型模式会让人把别人的满意当作安全来源。用户需要练习把“希望被喜欢”与“必须被喜欢才能安全”分开。可以从低风险场景练习表达偏好：今天我想吃这个、这个时间我不方便、我需要考虑一下。每一次没有迎合却仍然安全，都会给神经系统新证据。边界不是突然强硬，而是逐步把自我带回关系中。', '["讨好型人格", "边界", "关系", "自我价值", "安全感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 57, now()),
(100058, '关键对话开场：用共同目的降低防御', '高风险对话开始前，先不要急着陈述立场，而要建立共同目的。共同目的回答的是：我们为什么值得继续谈？例如“我不是想追责，而是想让之后合作更顺”“我想谈这件事，是因为这段关系对我重要”。当对方感到你不是来羞辱或控制，才可能从防御转向合作。事实、感受和请求都应服务于共同目的。', '["关键对话", "共同目的", "安全感", "高难沟通", "合作"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 58, now()),
(100059, '非暴力沟通的难点：请求必须具体且可拒绝', '非暴力沟通不只是温柔说话。很多人把要求伪装成请求，例如“你能不能尊重我一点”。真正的请求要具体、当下、可执行、可拒绝，如“今晚十点前能否把行程告诉我”。如果对方不能拒绝，那更像控制；如果不够具体，对方不知道怎么做。清楚请求能让关系从猜测和指责转向协商。', '["非暴力沟通", "请求", "需要", "边界", "关系沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 59, now()),
(100060, '共情不是同意，而是准确理解对方的内在经验', '共情力的重点不是替对方辩护，也不是放弃自己的立场，而是先准确复述对方的感受、需要和处境。有效共情常包含三层：你经历了什么，你因此有什么感受，这背后什么对你重要。共情之后仍可以设边界。比如“我听见你很委屈，也很想被支持；同时我不能接受用吼叫继续谈。”这样既连接，也不纵容。', '["共情", "倾听", "边界", "沟通", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 60, now()),
(100061, 'NLP地图：人回应的是自己的解释系统', '沟通中，别人不是直接回应现实，而是回应自己脑中的地图：经验、信念、价值和语言习惯。同一句话可能被理解成建议、批评、控制或关心。遇到误解时，不要只重复原话，可换一种感官通道和框架：给画面、给步骤、给感受、给选择。先理解对方地图，再邀请对方更新地图，比强迫对方接受自己的版本更有效。', '["NLP", "地图不是疆域", "沟通", "信念", "换框"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 61, now()),
(100062, '语言风格会透露关系位置和情绪距离', '语言风格资料提醒，词语不只传递内容，也传递关系位置。频繁使用绝对化词汇会增加压迫感；大量“你总是、你从不”容易引发防御；只讲道理不说感受，会让亲密关系变冷；过度道歉可能暴露低位和讨好。App 在润色沟通话术时，应把攻击性判断改成具体事实，把绝对化改成当下情境，把隐藏需求说清楚。', '["语言风格", "沟通", "关系位置", "表达", "冲突"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 62, now()),
(100063, '影响力原则：先建立可信度，再提出请求', '影响力不是操控，而是降低对方理解和决策成本。常见有效因素包括互惠、承诺一致、社会认同、喜好、权威和稀缺。但在关系和咨询场景中，最重要的是可信度与尊重。先说明共同利益、展示理解、给出选择，再提出具体请求。若只利用技巧压迫对方，即使短期有效，也会破坏信任。', '["影响力", "说服", "信任", "请求", "沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 63, now()),
(100064, '金字塔表达：先给结论，再给理由和行动', '用户需要向伴侣、客户或团队说明复杂问题时，可使用金字塔结构：先说核心结论，再给三到四个理由，最后给下一步行动。这样能减少对方在信息中的迷路感。情绪沟通也可借用：我的结论是我希望我们调整相处方式；理由是最近三次约定都失效、我感到不安、我仍重视关系；下一步是我们约定一个可执行规则。', '["金字塔原理", "表达结构", "沟通", "结论先行", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 64, now()),
(100065, '谈判不是压倒对方，而是扩大可交换资源', '谈判资料适合转化为关系协商建议：不要只盯一个立场，而要找背后的利益。双方争“谁对谁错”时，资源只有面子；转向“各自真正想保护什么”时，可能出现时间、方式、顺序、补偿、试行期等多个变量。好的谈判不是让一方认输，而是创造比僵持更好的交换方案。', '["谈判", "利益", "协商", "冲突解决", "双赢"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 65, now()),
(100066, '九型领导力：不同型号需要不同反馈方式', '九型用于管理和关系时，不是贴标签，而是调整沟通入口。1号重标准，反馈要具体且尊重其原则；2号重关系，先肯定付出再邀请表达需求；3号重成果，给清晰目标和真实反馈；4号重独特和意义，避免轻率否定感受；5号重边界，提前给信息；6号重安全，说明依据与风险；7号重自由，给选择；8号重直接，少绕弯；9号重和谐，要明确邀请其立场。', '["九型人格", "领导力", "反馈", "沟通", "团队"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 66, now()),
(100067, '人格识别：看注意力焦点，不只看外在行为', '同一种行为可能来自不同动机。努力工作可能是1号的责任、3号的成就、6号的安全、8号的掌控；照顾别人可能是2号的连接，也可能是9号避免冲突。识别九型时，应观察注意力自动被什么吸走：错误、需求、形象、缺失、边界、风险、可能性、力量还是和谐。动机比行为更稳定，也更适合给出成长建议。', '["九型人格", "识别方法", "动机", "注意力", "性格"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 67, now()),
(100068, '性格陷阱：早年适应策略长大后可能变成限制', '性格陷阱不是道德缺陷，而是曾经帮助人适应环境的策略在新场景中过度使用。比如过度警觉曾经保护自己，如今可能变成不信任；讨好曾经减少冲突，如今可能失去边界；控制曾经带来安全，如今可能压迫关系。成长不是否定过去的自己，而是感谢旧策略，再发展更多选择。', '["性格陷阱", "人格", "早年经验", "成长", "模式"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 68, now()),
(100069, '回避型模式：真正需要的不是消失，而是安全距离', '回避型用户常在关系变近时想逃，因为亲密被体验为压力、要求或失控。修复不是强迫自己立刻完全开放，而是学会表达安全距离：“我需要半小时冷静，但我会回来继续谈。”这样既保护空间，也减少对方被抛弃感。回避的成长方向，是把消失变成可预期的暂停，把独立变成有连接的独立。', '["回避型人格", "依恋", "亲密关系", "边界", "安全距离"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 69, now()),
(100070, '人格障碍资料的启发：先看长期模式和功能损害', '面对“TA 是不是某种人格障碍”的问题，App 不应轻易诊断，而要引导用户观察长期模式：是否跨场景反复出现，是否导致关系、工作或自我功能受损，是否难以通过普通沟通调整。可提供非诊断性建议：保护边界、记录事实、减少被拉入极端互动，必要时寻求专业评估。知识库应避免给人贴病理标签。', '["人格", "边界", "关系风险", "非诊断", "心理健康"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 70, now()),
(100071, '系统思考：不要只盯事件，要看结构和反馈回路', '系统思考提醒，很多问题不是单次事件，而是结构持续制造同样结果。关系里反复争吵，可能有追逃反馈回路；工作中总拖延，可能有目标过大、反馈太慢、奖励缺失的结构。提问时从“谁错了”升级为“什么结构让这个结果反复发生”。找到反馈回路后，改变一个杠杆点，比反复责备更有效。', '["系统思考", "反馈回路", "关系模式", "行为改变", "结构"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 71, now()),
(100072, '批判性提问：先问证据，再问替代解释', '学会提问适合提升 App 回答的思辨质量。用户陷入单一解释时，可引导其问：我有什么证据？证据是否可靠？还有没有其他解释？这个结论有没有忽略例外？如果最好的朋友遇到同样情况，我会怎样判断？批判性思维不是否定一切，而是让情绪化判断多经过一道证据和替代解释的过滤。', '["批判性思维", "提问", "证据", "替代解释", "认知"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 72, now()),
(100073, '第三选择：从你赢我输转向共同创造', '冲突中的两难常被卡成“按你的”或“按我的”。第三选择思维要求先暂停立场竞争，进入理解和共创：我先真正理解你，你也理解我，然后我们一起找一个比双方原方案更好的方案。它特别适合亲密关系和团队冲突，因为关系质量本身也是结果的一部分。不是折中到双方都不满意，而是扩大问题框架。', '["第三选择", "冲突解决", "共创", "协作", "思维模型"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 73, now()),
(100074, '社会性动物：人会被情境和群体强烈影响', '社会心理学提醒，人的行为不只来自性格，也受情境、规范、群体认同和他人期待影响。用户评价自己或他人时，不要过早归因为“人品就是这样”。可问：当时的压力、群体氛围、权威暗示、奖励惩罚、旁观者反应是什么？理解情境不是推卸责任，而是找到更有效的改变入口。', '["社会心理学", "情境", "群体", "归因", "行为"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 74, now()),
(100075, '态度改变：先降低威胁，再提供新经验', '态度很少因为被强行说服而改变。直接否定对方常会激发防御，让其更坚持原观点。更有效的是先承认其关切，再提供小的新经验或证据，让对方保留自尊地更新。亲密关系中也是如此：如果一开口就是“你错了”，对方会保护自我；如果先说“我理解你担心的是 X，同时我想补充 Y”，才更可能产生移动。', '["态度改变", "社会影响", "说服", "防御", "沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 75, now()),
(100076, '心智模型：同一问题要用多个镜头看', '高质量思维不是掌握一个万能模型，而是能切换镜头。遇到关系问题，可用依恋看安全感，用系统思考看互动回路，用非暴力沟通看需要，用九型看注意力焦点。遇到行动问题，可用习惯回路、福格模型和自控环境设计。多模型能避免把复杂人生简化成一句标签。', '["思维模型", "多元视角", "决策", "关系", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 76, now()),
(100077, '高品质思维：先选模型，再处理问题', '《30个高品质思维模型》OCR 后可提炼为一个实用原则：不要把所有问题都当成情绪、性格或努力问题。遇到选择困难，用机会成本和长期收益看；遇到反复冲突，用系统回路看；遇到沟通卡住，用换位和利益结构看；遇到目标失控，用拆解和反馈看。模型不是答案，而是提问方式。App 回答时可以先判断问题类型，再选择适合的思维框架，避免给出泛泛建议。', '["思维模型", "问题拆解", "决策", "系统思考", "反馈"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 77, now()),
(100078, '人际吸引和自尊：关系问题常牵动自我评价', '社会心理资料显示，人际反馈会强烈影响自我评价。用户被冷落或拒绝时，痛苦不只来自事件，也来自“我是不是不值得”的解释。支持时应把事件和价值拆开：一次回应慢，不等于你没有价值；一次关系失败，不等于你不适合被爱。先稳住自尊，再决定是否沟通、调整期待或离开。', '["自尊", "人际关系", "拒绝", "社会心理", "安全感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 78, now()),
(100079, '人生阶段：成长任务会随着年龄和角色改变', '成年发展心理学提醒，不同阶段的核心任务不同：建立身份、亲密关系、事业责任、照顾下一代、重新整合意义。用户的困惑不一定是退步，可能是旧阶段策略无法满足新阶段任务。App 回答时可问：你现在处在人生哪个转折？这个问题是在要求你发展什么新能力？这样能把焦虑转化为发展任务。', '["成年发展", "人生阶段", "成长任务", "身份", "意义"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 79, now()),
(100080, '人性的弱点：被重视感是沟通的底层需求', '人际沟通中，很多人首先需要感到被尊重、被看见、被认真对待。赞美、记住名字、真诚兴趣、少批评多理解，并不是讨好技巧，而是在满足基本的被重视需求。用于 App 建议时，应避免机械取悦，而是提醒用户：先让对方感到自己不是被审判的对象，再提出观点或请求。', '["人际沟通", "尊重", "被看见", "关系", "表达"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 80, now()),
(100081, 'NLP目标框架：把愿望改写成可执行结果', 'NLP 资料适合转化为 App 的目标澄清工具：不要只说“我不要焦虑、不要吵架、不要拖延”，而要改成正向、具体、可验证、由自己能启动的结果。例如“我想在冲突开始后先暂停三十秒，再用事实和需要表达”。一个好目标要能回答：我想要什么，何时何地发生，如何知道达成，它对我和关系是否生态，第一步由谁开始。这样能把模糊愿望转为行动脚本。', '["NLP", "目标设定", "行为改变", "可执行", "正向目标"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 81, now()),
(100082, 'NLP感知位置：从我、你、旁观者三角度重看冲突', '处理冲突时，可用 NLP 的感知位置练习。第一位置是我：我看见什么、感到什么、需要什么；第二位置是对方：如果我是 TA，可能害怕什么、想保护什么；第三位置是旁观者：一个中立的人会如何描述双方互动。用户卡在委屈或愤怒中时，不要求立刻原谅，而是先切换观察位置。位置切换能降低单一叙事的黏性，让沟通从控诉转向理解和选择。', '["NLP", "感知位置", "换位思考", "冲突修复", "沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 82, now()),
(100083, 'NLP逻辑层次：别在身份层攻击，只在行为层调整', '沟通中最容易伤人的错误，是把行为问题上升到身份否定：“你就是自私”“我就是没用”。NLP 的逻辑层次可帮助拆分：环境、行为、能力、信念价值、身份、使命。越高层越敏感，越低层越可改。反馈别人时，应尽量落在具体行为和影响上；鼓励自己时，可以把失败从身份层降回策略层：不是我不行，而是这个方法、环境或能力训练还需要调整。', '["NLP", "逻辑层次", "身份", "反馈", "自我价值"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 83, now()),
(100084, 'NLP亲和感：先校准对方状态，再推动观点', '高效沟通不是急着输出观点，而是先建立亲和感。亲和不等于讨好，而是观察对方的节奏、情绪、用词和关注点，让对方感到被接上。用户想说服或修复关系时，可先复述对方关键词，确认理解，再提出自己的需要。若对方在压力中，先降低语速、减少结论、给出选择；若对方重结果，就给结构和下一步。先连接频道，再传递内容。', '["NLP", "亲和感", "校准", "影响力", "沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 84, now()),
(100085, 'NLP换框：问题行为背后常有未被满足的正向意图', '换框不是强行积极，而是寻找行为背后的功能。拖延可能在保护人免于羞耻，冷处理可能在保护人免于被淹没，控制可能在追求安全。识别正向意图后，仍要评估旧策略是否有代价，再寻找更成熟的替代方式。这样既不纵容问题行为，也不把人简单定罪。App 在回答关系和成长问题时，可先问“这个反应原本想帮你避免什么”。', '["NLP", "换框", "正向意图", "行为模式", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 85, now()),
(100086, '语言风格：功能词比大道理更透露心理状态', '语言风格资料强调，真正透露心理状态的往往不是华丽内容词，而是人称、虚词、连接词、否定词、时态等小词。一个人频繁使用“我”可能处在自我关注或压力中；大量绝对化词汇会让表达更封闭；过多否定和转折可能显示防御或矛盾。用于 App 时，不应把单个词当诊断，而是把语言线索作为理解用户情绪、关系位置和注意力焦点的辅助证据。', '["语言风格", "功能词", "心理线索", "自我觉察", "沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 86, now()),
(100087, '人称代词：我、你、我们会改变关系气氛', '沟通话术里，人称代词会影响关系气氛。只说“你怎么总是”容易让对方感到被审判；只说“我都怪我”容易让自己陷入低位；适度使用“我们”能提示共同面对问题，但若用“我们”掩盖个人责任，也会显得逃避。更成熟的表达是：我为自己的感受和请求负责，你为你的选择负责，我们一起决定下一步规则。', '["人称代词", "关系沟通", "责任", "表达", "语言风格"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 87, now()),
(100088, '语言同步：相似的表达节奏能增加被理解感', '语言风格研究提示，人在连接顺畅时，表达节奏、词类和关注点会自然靠近。关系沟通中，可以有意识地先使用对方熟悉的词和框架，再提出新观点。比如对方重视效率，就先谈结果和步骤；对方重视感受，就先谈体验和影响。同步不是模仿操控，而是降低理解成本。同步之后再温和引入不同意见，通常比直接反驳更容易被听见。', '["语言同步", "沟通", "亲和感", "表达节奏", "理解"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 88, now()),
(100089, '从绝对化语言回到具体事实', '冲突中的“总是、从不、每次、所有人都”会迅速放大威胁，让对方进入辩解。语言风格资料可用于提醒用户把绝对化改成具体事实：把“你从来不关心我”改成“这周三次我提到难受时，你都没有继续问”；把“我永远做不好”改成“这次演示有两处没有准备充分”。事实越具体，越能讨论；标签越绝对，越容易卡住。', '["绝对化语言", "事实表达", "冲突降温", "沟通", "认知"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 89, now()),
(100090, '书写能帮助整理情绪叙事', '语言与心理研究显示，把混乱经历写出来，能帮助人把情绪、事实和意义重新组织。App 可以引导用户做三段式书写：发生了什么；我当时有哪些感受和身体反应；这件事触碰了我什么需要，以及下一步我能做什么。书写不是为了美化痛苦，而是把脑内反刍转为外部文本，使人更容易看见模式、选择行动。', '["书写疗愈", "情绪整理", "反刍", "语言", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 90, now()),
(100091, '九型发展层级：同一型号也有健康和失衡差异', '《九型人格2》强调，同一人格类型不是固定表现，而会随健康水平呈现不同层级。健康状态下，类型天赋会服务于生命：1号正直、2号慈悲、3号真实高效、4号创造、5号洞察、6号勇敢、7号喜悦、8号保护、9号安定。失衡时，同一能量会扭曲成批判、索取、表演、沉溺、抽离、怀疑、逃避、控制或麻木。因此 App 使用九型时，应同时判断主型和状态，而不是看到一个行为就定型。', '["九型人格", "发展层级", "健康状态", "失衡", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 91, now()),
(100092, '九型误判：理想自我不等于真实类型', '很多人测九型时会把“我想成为的人”误认为“我真实的自动策略”。例如想显得善良而选2号，想显得强大而选8号，想显得理性而选5号。更可靠的识别方式，是看压力下最自动的防御、反复出现的恐惧和注意力焦点。真正的类型常让人有一点被看穿，而不只是感觉很喜欢。App 解读时应提示用户：问卷只是入口，动机和长期模式更重要。', '["九型人格", "误判", "理想自我", "动机", "识别方法"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 92, now()),
(100093, '九型应用：不要用类型限制人，要用类型增加选择', '九型知识容易被误用成标签：“我是6号所以我就是焦虑”“他是8号所以没法沟通”。更成熟的用法是看见自动模式，然后增加选择。类型解释了为什么某些问题反复出现，但不决定人只能这样。App 回答应避免“你就是某型所以必然如何”，而应说“如果你有这种模式，可以尝试发展相反能力”。九型的目标是自由，不是把人关进九个盒子。', '["九型人格", "标签风险", "自由", "成长", "自我超越"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 93, now()),
(100094, '九型矛盾感：人会在不同场景表现出多个类型影子', '用户常问“为什么我像好几个型号”。九型人格2的一个实用提醒是：人会在不同关系、压力和角色中呈现多个类型的影子，但核心类型仍看最深层动机和防御。一个人可以既慷慨又自私，既温和又攻击，既理性又情绪化；这些矛盾不一定说明类型混乱，而可能是侧翼、压力线、安全线、健康层级和社会角色共同作用。识别时要看长期重复的主旋律。', '["九型人格", "侧翼", "压力线", "情境", "识别方法"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 94, now()),
(100095, '九型关系建议：先看对方害怕失去什么', '九型用于关系沟通时，可以先问“这个型号最怕失去什么”。1号怕失去正确和尊严，2号怕失去被需要，3号怕失去价值和认可，4号怕失去真实自我，5号怕失去空间和资源，6号怕失去安全和支持，7号怕失去自由和可能性，8号怕失去掌控和脆弱保护，9号怕失去和谐。理解恐惧后，沟通更容易避开对方防御，也更能提出对方听得进去的请求。', '["九型人格", "关系沟通", "核心恐惧", "防御", "理解他人"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v3-20260705', 95, now())
